/* Ready-made content. Everything here is generated by code from small tables, or written out, so it can be counted and checked:
 *   TASK_IDEAS 100, STUDY_TIPS 100, CAL_IDEAS 100, STARTER_DECKS 6 decks with 251 cards. */
export const SUBJECTS = ['Mathematics', 'English', 'Kinyarwanda', 'Biology', 'Chemistry', 'Physics', 'History', 'Geography', 'Computer Science', 'Entrepreneurship'];

const TASK_PATTERNS = [
  s => `${s}: read today's notes and underline 5 key points`, s => `${s}: write a one-page summary of this week's lesson`, s => `${s}: do 10 practice questions`,
  s => `${s}: make 10 flashcards for the hardest ideas`, s => `${s}: explain one topic aloud as if teaching a friend`, s => `${s}: correct the mistakes from the last test`,
  s => `${s}: finish the homework before supper`, s => `${s}: ask the teacher about one thing I did not understand`, s => `${s}: do a 20-minute past-paper section`, s => `${s}: plan next week's ${s} revision`,
];
export const TASK_IDEAS = SUBJECTS.flatMap(s => TASK_PATTERNS.map(p => ({ subject: s, title: p(s) })));

const CAL_KINDS = [['Exam', 'exam'], ['Class test', 'exam'], ['Revision session', 'lesson'], ['Homework due', 'event'], ['Project deadline', 'event'],
  ['Parents’ meeting about', 'meeting'], ['Study group', 'lesson'], ['Club meeting for', 'meeting'], ['Practical lesson', 'lesson'], ['Presentation in', 'event']];
export const CAL_IDEAS = CAL_KINDS.flatMap(([k, kind]) => SUBJECTS.map(s => ({ title: /about$|for$|in$/.test(k) ? `${k} ${s}` : `${s} ${k.toLowerCase()}`, kind, subject: s })));

/* ---- starter flashcard decks (answers computed, never typed) ---- */
const ord = n => n + (n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th');
const primes = (() => { const p = []; for (let n = 2; p.length < 25; n++) if (p.every(x => n % x)) p.push(n); return p; })();
const VERBS = [['go', 'went', 'gone'], ['see', 'saw', 'seen'], ['eat', 'ate', 'eaten'], ['write', 'wrote', 'written'], ['take', 'took', 'taken'], ['give', 'gave', 'given'], ['speak', 'spoke', 'spoken'], ['break', 'broke', 'broken'], ['choose', 'chose', 'chosen'], ['drive', 'drove', 'driven'], ['begin', 'began', 'begun'], ['drink', 'drank', 'drunk'], ['sing', 'sang', 'sung'], ['swim', 'swam', 'swum'], ['ring', 'rang', 'rung'], ['know', 'knew', 'known'], ['grow', 'grew', 'grown'], ['throw', 'threw', 'thrown'], ['fly', 'flew', 'flown'], ['draw', 'drew', 'drawn'], ['wear', 'wore', 'worn'], ['tear', 'tore', 'torn'], ['steal', 'stole', 'stolen'], ['forget', 'forgot', 'forgotten'], ['rise', 'rose', 'risen']];
const gcd = (a, b) => (b ? gcd(b, a % b) : a);
const FRACS = []; for (let d = 2; d <= 20 && FRACS.length < 20; d++) for (let n = 1; n < d && FRACS.length < 20; n++) if (gcd(n, d) === 1 && (100 * n) % d === 0 && d !== 100) FRACS.push([n, d]);
export const STARTER_DECKS = [
  { title: 'Squares 1 to 25', subject: 'Mathematics', cards: Array.from({ length: 25 }, (_, i) => [`${i + 1}² = ?`, String((i + 1) ** 2)]) },
  { title: 'Cubes 1 to 12', subject: 'Mathematics', cards: Array.from({ length: 12 }, (_, i) => [`${i + 1}³ = ?`, String((i + 1) ** 3)]) },
  { title: 'Times tables 1 to 12', subject: 'Mathematics', cards: Array.from({ length: 144 }, (_, i) => { const a = Math.floor(i / 12) + 1, b = (i % 12) + 1; return [`${a} × ${b} = ?`, String(a * b)]; }) },
  { title: 'First 25 prime numbers', subject: 'Mathematics', cards: primes.map((p, i) => [`What is the ${ord(i + 1)} prime number?`, String(p)]) },
  { title: 'Fractions as percentages', subject: 'Mathematics', cards: FRACS.map(([n, d]) => [`${n}/${d} as a percentage?`, `${(100 * n) / d}%`]) },
  { title: 'Irregular verbs', subject: 'English', cards: VERBS.map(([a, b, c]) => [`Past simple and past participle of "${a}"?`, `${b}, ${c}`]) },
];

/* ---- 100 study tips, ten themes of ten ---- */
export const TIP_THEMES = ['Focus', 'Memory', 'Reading', 'Maths', 'Writing', 'Exams', 'Habits', 'Health', 'Group work', 'Mindset'];
export const STUDY_TIPS = [
  /* Focus */ ['Study in short bursts of 25 minutes, then rest for 5.', 'Put your phone in another room while you study.', 'Write the one goal of this session before you start.', 'Clear your desk of everything you do not need.', 'Study the hardest subject first, while you are fresh.', 'If your mind wanders, write the distraction down and return to work.', 'Use the same place for study so your brain learns it means work.', 'Tell someone what you will finish today.', 'Switch subjects after an hour to stay alert.', 'Stop when the timer ends and rest properly; breaks make the next round better.'],
  /* Memory */ ['Test yourself instead of rereading; recalling is what builds memory.', 'Review new material the same day, then after 2 days, then a week.', 'Explain an idea in your own words without looking.', 'Turn a list into a story or a funny sentence.', 'Draw the idea; pictures stick better than lines of text.', 'Teach a younger sibling or friend what you learned.', 'Make flashcards with one question on each.', 'Sleep after studying; sleep is when memories settle.', 'Link new facts to something you already know.', 'Say it aloud while walking; movement helps recall.'],
  /* Reading */ ['Skim headings first so you know where the chapter is going.', 'Turn each heading into a question and read to answer it.', 'Underline less. Write a margin note instead.', 'After each page, close the book and say the main idea.', 'Look up every new word and write its meaning beside it.', 'Read the summary at the end of a chapter before the chapter.', 'Slow down for diagrams; they hold many marks.', 'Keep a list of questions as you read and ask them in class.', 'Re-read the hardest paragraph aloud.', 'Read a little every day; ten pages beat one long night.'],
  /* Maths */ ['Practice problems beat reading solutions. Try first, then check.', 'Write every step; most lost marks hide in skipped steps.', 'Learn why a formula works, not only how to use it.', 'Redo questions you got wrong a week later.', 'Estimate the answer first to catch silly mistakes.', 'Check units on every line.', 'When stuck, try a smaller number or draw a picture.', 'Keep a list of formulas and tick the ones you can write from memory.', 'Time yourself on a set of questions to build speed.', 'Make up your own question about each topic and solve it.'],
  /* Writing */ ['Plan with three bullet points before you write a paragraph.', 'Start each paragraph with its main point.', 'Write a rough draft first and fix it afterwards.', 'Read your work aloud to hear clumsy sentences.', 'Replace long words with simple ones when they mean the same.', 'Give one example for every claim.', 'Keep sentences short when the idea is hard.', 'Check spelling of names and key terms last.', 'End with one sentence that answers the question again.', 'Keep a notebook of good phrases you meet while reading.'],
  /* Exams */ ['Make a revision timetable and start two weeks early.', 'Practice with past papers under real time limits.', 'Read the whole paper first and mark the questions you can answer fast.', 'Spend time in proportion to the marks.', 'Underline the command word: explain, compare, describe.', 'If stuck, move on and return at the end.', 'Leave five minutes to check your answers.', 'Prepare your pens, ruler and calculator the night before.', 'Eat breakfast and drink water on exam day.', 'After the exam, do not replay it; start preparing for the next.'],
  /* Habits */ ['Study at the same time each day so it becomes automatic.', 'Start with just five minutes; starting is the hard part.', 'Tick off each day on a calendar; do not break the chain.', 'Pack your bag the evening before.', 'Reward yourself after a finished task.', 'Keep a short to-do list with at most three main items.', 'Review your week every Sunday and plan the next.', 'Say no to one distraction every day.', 'Keep your notes in one place and date every page.', 'Small steps every day beat a big push once a month.'],
  /* Health */ ['Sleep eight hours; tired brains learn badly.', 'Drink water while studying.', 'Walk for ten minutes between study blocks.', 'Eat real meals; hungry minds cannot focus.', 'Rest your eyes by looking far away every 20 minutes.', 'Sit with your back straight and feet on the floor.', 'Take three slow breaths before a test.', 'Spend some time outside in daylight each day.', 'Talk to someone you trust when you feel overloaded.', 'Rest is part of studying, not a waste of it.'],
  /* Group work */ ['Study with a friend who asks you hard questions.', 'Take turns teaching each other one topic.', 'Agree on a goal and a time limit before you meet.', 'Quiz each other with flashcards.', 'Share notes but write your own summary.', 'Ask the quiet member what they think.', 'Split a big topic and teach your part.', 'Keep phones away during group study.', 'Finish by writing three things you each learned.', 'Be kind about mistakes; everyone is learning.'],
  /* Mindset */ ['A wrong answer is information, not failure.', 'Say "I cannot do this yet" instead of "I cannot".', 'Compare yourself with last month, not with others.', 'Celebrate small wins in writing.', 'Ask for help early; it saves time.', 'Hard feels hard because your brain is growing.', 'Picture yourself finishing, then take the first step.', 'Remember why you are studying and write it on your desk.', 'Mistakes in practice are cheaper than mistakes in exams.', 'Keep going. Slow progress is still progress.'],
].flatMap((list, t) => list.map(text => ({ theme: TIP_THEMES[t], text })));

export const COUNTS = { tasks: TASK_IDEAS.length, tips: STUDY_TIPS.length, events: CAL_IDEAS.length, deckCards: STARTER_DECKS.reduce((n, d) => n + d.cards.length, 0), decks: STARTER_DECKS.length };
